<?php
session_start();
require_once __DIR__.'/../includes/config.php';
if(!isset($conn)||!($conn instanceof mysqli))die('Database connection is not available.');
if(empty($_SESSION['admin_logged_in'])){header('Location: admin-login.php');exit;}
function h($v){return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}
$conn->query("CREATE TABLE IF NOT EXISTS rider_cod_settlements(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,rider_id INT UNSIGNED NOT NULL,wallet_id VARCHAR(50) NOT NULL,amount DECIMAL(12,2) NOT NULL DEFAULT 0,payment_method VARCHAR(40) NOT NULL DEFAULT '',reference_no VARCHAR(120) NULL,status ENUM('pending','approved','rejected') NOT NULL DEFAULT 'pending',admin_note VARCHAR(255) NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,verified_at DATETIME NULL,INDEX(rider_id,status)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");
$msg='';$err='';
if($_SERVER['REQUEST_METHOD']==='POST'){
 $id=(int)($_POST['rider_id']??0);$action=(string)($_POST['action']??'');
 if($action==='settlement_approve'||$action==='settlement_reject'){
  $sid=(int)($_POST['settlement_id']??0);$new=$action==='settlement_approve'?'approved':'rejected';
  $s=$conn->prepare("UPDATE rider_cod_settlements SET status=?,verified_at=NOW() WHERE id=? AND status='pending'");
  if($s){$s->bind_param('si',$new,$sid);$s->execute();$ok=$s->affected_rows>0;$s->close();$ok? $msg='COD settlement '.($new==='approved'?'approved':'rejected').'.':$err='Settlement is no longer pending.';}
 }elseif($id>0 && in_array($action,['approve','reject','restrict','unrestrict'],true)){
  $map=['approve'=>'active','reject'=>'inactive','restrict'=>'blocked','unrestrict'=>'active'];$status=$map[$action];
  $s=$conn->prepare('UPDATE riders SET status=? WHERE id=? LIMIT 1');
  if($s){$s->bind_param('si',$status,$id);$s->execute();$ok=$s->affected_rows>=0;$s->close();$msg=$ok?'Rider status updated successfully.':'Unable to update rider.';}
 }
}
$filter=strtolower(trim($_GET['status']??'all'));$allowed=['all','pending','active','inactive','blocked'];if(!in_array($filter,$allowed,true))$filter='all';$search=trim($_GET['search']??'');
$riders=[];$sql="SELECT id,full_name,email,phone,cnic,vehicle_type,bike_number,address,status,availability_status,created_at FROM riders";$w=[];$p=[];$t='';
if($filter!=='all'){$w[]='status=?';$p[]=$filter;$t.='s';}if($search!==''){$w[]='(full_name LIKE ? OR email LIKE ? OR phone LIKE ? OR cnic LIKE ? OR bike_number LIKE ?)';$x='%'.$search.'%';for($i=0;$i<5;$i++)$p[]=$x;$t.='sssss';}if($w)$sql.=' WHERE '.implode(' AND ',$w);$sql.=' ORDER BY created_at DESC';
$s=$conn->prepare($sql);if($s){if($p)$s->bind_param($t,...$p);$s->execute();$r=$s->get_result();while($x=$r->fetch_assoc())$riders[]=$x;$s->close();}
$viewId=(int)($_GET['view']??0);$view=null;$wallet=[];$settlements=[];$earnTotal=0;$codTotal=0;$codPayable=0;$codPaid=0;
if($viewId>0){$s=$conn->prepare('SELECT * FROM riders WHERE id=? LIMIT 1');$s->bind_param('i',$viewId);$s->execute();$view=$s->get_result()->fetch_assoc();$s->close();
 $conn->query("CREATE TABLE IF NOT EXISTS rider_payouts(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,rider_id INT UNSIGNED NOT NULL,order_id BIGINT UNSIGNED NULL,amount DECIMAL(12,2) NOT NULL DEFAULT 0,status ENUM('pending','approved','paid','cancelled') NOT NULL DEFAULT 'pending',paid_at DATETIME NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX(rider_id,status),INDEX(order_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");
 $s=$conn->prepare("SELECT COALESCE(SUM(amount),0) total FROM rider_payouts WHERE rider_id=? AND status<>'cancelled'");$s->bind_param('i',$viewId);$s->execute();$earnTotal=(float)$s->get_result()->fetch_assoc()['total'];$s->close();
 $conn->query("CREATE TABLE IF NOT EXISTS rider_cod_wallet(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,rider_id INT UNSIGNED NOT NULL,order_id BIGINT UNSIGNED NOT NULL,cod_amount DECIMAL(12,2) NOT NULL DEFAULT 0,rider_earning DECIMAL(12,2) NOT NULL DEFAULT 0,net_payable DECIMAL(12,2) NOT NULL DEFAULT 0,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY uq_rider_order(rider_id,order_id),INDEX(rider_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");
 $s=$conn->prepare("SELECT COALESCE(SUM(cod_amount),0) cod,COALESCE(SUM(net_payable),0) payable FROM rider_cod_wallet WHERE rider_id=?");$s->bind_param('i',$viewId);$s->execute();$z=$s->get_result()->fetch_assoc();$codTotal=(float)$z['cod'];$codPayable=(float)$z['payable'];$s->close();
 $s=$conn->prepare("SELECT COALESCE(SUM(amount),0) total FROM rider_cod_settlements WHERE rider_id=? AND status='approved'");$s->bind_param('i',$viewId);$s->execute();$codPaid=(float)$s->get_result()->fetch_assoc()['total'];$s->close();
 $s=$conn->prepare("SELECT * FROM rider_cod_settlements WHERE rider_id=? ORDER BY id DESC");$s->bind_param('i',$viewId);$s->execute();$r=$s->get_result();while($x=$r->fetch_assoc())$settlements[]=$x;$s->close();
}
$count=['total'=>0,'pending'=>0,'active'=>0,'inactive'=>0,'blocked'=>0];$q=$conn->query("SELECT COUNT(*) total,SUM(status='pending') pending,SUM(status='active') active,SUM(status='inactive') inactive,SUM(status='blocked') blocked FROM riders");if($q)$count=array_map('intval',$q->fetch_assoc());
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Manage Riders</title><style>*{box-sizing:border-box}body{margin:0;background:#fff8fb;font:14px Segoe UI,Arial;color:#222}.main{margin-left:218px;padding:25px}.stats{display:grid;grid-template-columns:repeat(5,1fr);gap:12px;margin:18px 0}.stat,.card{background:#fff;border:1px solid #f0dfe7;border-radius:14px;padding:16px}.stat b{display:block;font-size:23px;margin-top:6px}.toolbar{display:flex;gap:8px;margin:15px 0}.toolbar input,.toolbar select{padding:11px;border:1px solid #ddd;border-radius:8px}.toolbar input{flex:1}.btn{border:0;border-radius:8px;padding:9px 12px;font-weight:800;cursor:pointer;background:#ed0038;color:#fff}.btn.green{background:#e8f8ef;color:#16834a}.btn.red{background:#ffe8ec;color:#c00032}.btn.gray{background:#eee;color:#555}.btn.blue{background:#eaf4ff;color:#1667a8}.table{width:100%;border-collapse:collapse;background:#fff}.table th,.table td{padding:12px;border-bottom:1px solid #eee;text-align:left;font-size:12px}.pill{padding:5px 9px;border-radius:20px;font-size:11px;font-weight:800}.online{background:#e8f8ef;color:#16834a}.offline{background:#eee;color:#666}.pending{background:#fff0d8;color:#a65b00}.blocked{background:#ffe8ec;color:#c00032}.actions{display:flex;gap:5px;flex-wrap:wrap}.modal{background:#fff;border:2px solid #ed0038;border-radius:15px;padding:20px;margin:18px 0}.grid{display:grid;grid-template-columns:repeat(4,1fr);gap:10px}.box{background:#fafafa;border:1px solid #eee;border-radius:10px;padding:12px}.box small{display:block;color:#777}.box b{display:block;margin-top:4px}.history{width:100%;border-collapse:collapse;margin-top:12px}.history th,.history td{padding:10px;border-bottom:1px solid #eee;text-align:left;font-size:11px}.msg{padding:12px;border-radius:9px;background:#e8f8ef;color:#176c36;margin-bottom:12px}.err{background:#fff0f3;color:#a0002d}@media(max-width:900px){.main{margin-left:0;padding:15px}.stats,.grid{grid-template-columns:1fr 1fr}.table{display:block;overflow:auto;white-space:nowrap}}@media(max-width:550px){.stats,.grid{grid-template-columns:1fr}}</style></head><body><?php include __DIR__.'/admin-sidebar.php';?><main class="main"><h1>Manage Riders</h1><p style="color:#777">Approve riders, control access and view earnings/COD settlements.</p><?php if($msg):?><div class="msg"><?=h($msg)?></div><?php endif;?><?php if($err):?><div class="msg err"><?=h($err)?></div><?php endif;?><div class="stats"><div class="stat">Total Riders<b><?=$count['total']?></b></div><div class="stat">Pending<b><?=$count['pending']?></b></div><div class="stat">Approved<b><?=$count['active']?></b></div><div class="stat">Inactive<b><?=$count['inactive']?></b></div><div class="stat">Restricted<b><?=$count['blocked']?></b></div></div><?php if($view):?><section class="modal"><div style="display:flex;justify-content:space-between"><h2>Rider Details — <?=h($view['full_name'])?></h2><a class="btn gray" href="manage-riders.php">Close View</a></div><div class="grid"><div class="box"><small>Name</small><b><?=h($view['full_name'])?></b></div><div class="box"><small>Contact</small><b><?=h($view['phone'])?><br><?=h($view['email'])?></b></div><div class="box"><small>CNIC</small><b><?=h($view['cnic']?:'—')?></b></div><div class="box"><small>Vehicle Number</small><b><?=h($view['bike_number']?:'—')?></b></div><div class="box"><small>Account</small><b><?=h(ucfirst($view['status']))?></b></div><div class="box"><small>Current Status</small><b><?=strtolower((string)$view['availability_status'])==='offline'?'Offline':'Online'?></b></div><div class="box"><small>Total Earning</small><b>Rs <?=number_format($earnTotal,2)?></b></div><div class="box"><small>Total COD</small><b>Rs <?=number_format($codTotal,2)?></b></div><div class="box"><small>COD Settled</small><b>Rs <?=number_format($codPaid,2)?></b></div><div class="box"><small>COD Outstanding</small><b>Rs <?=number_format(max(0,$codPayable-$codPaid),2)?></b></div></div><h3>COD Settlement History</h3><table class="history"><tr><th>Date</th><th>Amount</th><th>Method</th><th>Reference</th><th>Status</th><th>Action</th></tr><?php foreach($settlements as $x):?><tr><td><?=h($x['created_at'])?></td><td>Rs <?=number_format((float)$x['amount'],2)?></td><td><?=h($x['payment_method'])?></td><td><?=h($x['reference_no']?:'—')?></td><td><span class="pill <?=h($x['status'])?>"><?=h(ucfirst($x['status']))?></span></td><td><?php if($x['status']==='pending'):?><form method="post" style="display:inline"><input type="hidden" name="settlement_id" value="<?=$x['id']?>"><input type="hidden" name="action" value="settlement_approve"><button class="btn green">Approve</button></form><form method="post" style="display:inline"><input type="hidden" name="settlement_id" value="<?=$x['id']?>"><input type="hidden" name="action" value="settlement_reject"><button class="btn red">Reject</button></form><?php else:?>—<?php endif;?></td></tr><?php endforeach;?></table></section><?php endif;?><form class="toolbar" method="get"><input name="search" value="<?=h($search)?>" placeholder="Search name, phone, CNIC, vehicle..."><select name="status"><option value="all">All</option><option value="pending" <?=$filter==='pending'?'selected':''?>>Pending</option><option value="active" <?=$filter==='active'?'selected':''?>>Approved</option><option value="blocked" <?=$filter==='blocked'?'selected':''?>>Restricted</option><option value="inactive" <?=$filter==='inactive'?'selected':''?>>Inactive</option></select><button class="btn">Filter</button></form><section class="card" style="padding:0;overflow:auto"><table class="table"><tr><th>Rider</th><th>Contact</th><th>CNIC</th><th>Vehicle</th><th>Status</th><th>Actions</th></tr><?php foreach($riders as $r):$st=strtolower((string)$r['status']);$av=strtolower((string)($r['availability_status']??'offline'));?><tr><td><b><?=h($r['full_name'])?></b><br><small>Rider #<?=h($r['id'])?></small></td><td><?=h($r['phone'])?><br><small><?=h($r['email'])?></small></td><td><?=h($r['cnic']?:'—')?></td><td><?=h($r['bike_number']?:'—')?></td><td><span class="pill <?=$av==='offline'?'offline':'online'?>"><?= $av==='offline'?'Offline':'Online'?></span></td><td><div class="actions"><?php if($st==='pending'):?><form method="post"><input type="hidden" name="rider_id" value="<?=$r['id']?>"><button class="btn green" name="action" value="approve">Approve</button></form><?php elseif($st==='active'):?><form method="post"><input type="hidden" name="rider_id" value="<?=$r['id']?>"><button class="btn red" name="action" value="restrict">Restrict</button></form><?php elseif($st==='blocked'):?><form method="post"><input type="hidden" name="rider_id" value="<?=$r['id']?>"><button class="btn blue" name="action" value="unrestrict">Unrestrict</button></form><?php endif;?><a class="btn gray" href="?view=<?=$r['id']?>">View</a></div></td></tr><?php endforeach;?></table></section></main></body></html>